# 32x32 byte matrix multiply, ijk loop order (MMA).
#   A at 0x2000, B at 0x3000, C at 0x4000.  Generated by
#   scripts/generate_matmul.py — DO NOT EDIT BY HAND.

_start:
    lui  sp, 0xC
    lui  s0, 0x2          # A = 0x2000
    lui  s1, 0x3          # B = 0x3000
    lui  s2, 0x4          # C = 0x4000
    addi s3, x0, 32

    addi s4, x0, 0
i_loop:
    bge  s4, s3, mm_end
    addi s5, x0, 0
j_loop:
    bge  s5, s3, j_end
    addi s6, x0, 0
    addi s7, x0, 0
k_loop:
    bge  s7, s3, k_end
    slli t0, s4, 5
    add  t0, t0, s7
    add  t0, s0, t0
    lb   a0, 0(t0)
    slli t1, s7, 5
    add  t1, t1, s5
    add  t1, s1, t1
    lb   a1, 0(t1)
    jal  ra, mul
    add  s6, s6, a0
    addi s7, s7, 1
    jal  x0, k_loop
k_end:
    slli t0, s4, 5
    add  t0, t0, s5
    add  t0, s2, t0
    sb   s6, 0(t0)
    addi s5, s5, 1
    jal  x0, j_loop
j_end:
    addi s4, s4, 1
    jal  x0, i_loop
mm_end:
    ebreak

mul:
    addi t6, x0, 0
    andi a1, a1, 0xff
    beq  a1, x0, mul_done
mul_loop:
    add  t6, t6, a0
    addi a1, a1, -1
    bne  a1, x0, mul_loop
mul_done:
    add  a0, t6, x0
    jalr x0, 0(ra)
